<script setup>
import { onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { getBills, getBillDetail } from '../../api/bill.js'
import { getCommunities } from '../../api/community.js'
import { apiMessage } from '../../api/http.js'
import PageHeader from '../../components/common/PageHeader.vue'
import PaginationBar from '../../components/common/PaginationBar.vue'
import SectionCard from '../../components/common/SectionCard.vue'
import StatusTag from '../../components/common/StatusTag.vue'
import { formatMoney } from '../../constants/presentation.js'
const q=reactive({communityId:null,year:2026,month:7,status:'',propertyKeyword:'',page:1,pageSize:20}), rows=ref([]), total=ref(0), loading=ref(false), communities=ref([]), drawer=ref(false), detail=ref(null)
const statuses={PAID:'已缴清',PARTIALLY_PAID:'部分缴费',OVERDUE:'已逾期'}
async function load(){loading.value=true;try{const r=await getBills(q);rows.value=r.records;total.value=r.total}catch(e){ElMessage.error(apiMessage(e,'账单加载失败'))}finally{loading.value=false}}
async function open(r){try{detail.value=await getBillDetail(r.billId);drawer.value=true}catch(e){ElMessage.error(apiMessage(e))}}
function onPageChange(){load()}
onMounted(async()=>{communities.value=await getCommunities();load()})
</script>
<template><section class="page"><PageHeader title="物业账单" description="按账期与房产查看应收、实收和欠费；账单明细与支付记录均来自真实业务数据。"/><SectionCard title="账单列表" :description="`当前筛选结果共 ${total} 条`"><div class="filters"><el-input v-model="q.propertyKeyword" clearable placeholder="小区或房产位置" @keyup.enter="q.page=1;load()"/><el-select v-model="q.communityId" clearable placeholder="全部小区"><el-option v-for="c in communities" :key="c.communityId" :label="c.communityName" :value="c.communityId"/></el-select><el-input-number v-model="q.year" :min="2000" :max="2200" controls-position="right"/><el-select v-model="q.month"><el-option v-for="m in 12" :key="m" :label="`${m} 月`" :value="m"/></el-select><el-select v-model="q.status" clearable placeholder="账单状态"><el-option v-for="(v,k) in statuses" :key="k" :label="v" :value="k"/></el-select><el-button type="primary" @click="q.page=1;load()">查询</el-button></div><el-table v-loading="loading" :data="rows" class="business-table"><el-table-column prop="fullLocation" label="完整房产位置" min-width="260"/><el-table-column prop="billNo" label="账单号" min-width="155"/><el-table-column label="账期"><template #default="{row}">{{row.billingYear}}-{{String(row.billingMonth).padStart(2,'0')}}</template></el-table-column><el-table-column label="应收"><template #default="{row}">{{formatMoney(row.receivableAmount)}}</template></el-table-column><el-table-column label="实收"><template #default="{row}">{{formatMoney(row.receivedAmount)}}</template></el-table-column><el-table-column label="欠费"><template #default="{row}">{{formatMoney(row.outstandingAmount)}}</template></el-table-column><el-table-column prop="dueDate" label="截止日"/><el-table-column label="状态"><template #default="{row}"><StatusTag :value="row.status"/></template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link type="primary" @click="open(row)">查看详情</el-button></template></el-table-column></el-table><PaginationBar v-model:page="q.page" v-model:page-size="q.pageSize" :total="total" @change="onPageChange"/></SectionCard></section><el-drawer v-model="drawer" size="min(720px,100%)" title="账单详情"><template v-if="detail"><el-descriptions :column="2" border><el-descriptions-item label="完整位置">{{detail.communityName}} · {{detail.buildingName}} · {{detail.unitName}} · {{detail.propertyNo}}</el-descriptions-item><el-descriptions-item label="账单号">{{detail.billNo}}</el-descriptions-item><el-descriptions-item label="账期">{{detail.billingYear}}-{{String(detail.billingMonth).padStart(2,'0')}}</el-descriptions-item><el-descriptions-item label="出账日期">{{detail.issuedAt}}</el-descriptions-item><el-descriptions-item label="截止日期">{{detail.dueDate}}</el-descriptions-item><el-descriptions-item label="状态"><StatusTag :value="detail.status"/></el-descriptions-item><el-descriptions-item label="应收">{{formatMoney(detail.receivableAmount)}}</el-descriptions-item><el-descriptions-item label="实收">{{formatMoney(detail.receivedAmount)}}</el-descriptions-item><el-descriptions-item label="欠费">{{formatMoney(detail.outstandingAmount)}}</el-descriptions-item></el-descriptions><h3>账单项目</h3><el-table :data="detail.items" max-height="330"><el-table-column prop="feeName" label="项目"/><el-table-column label="计费方式"><template #default="{row}">{{row.billingMethod==='METERED'?'计量收费':row.billingMethod==='AREA'?'面积收费':'固定收费'}}</template></el-table-column><el-table-column label="上期读数"><template #default="{row}">{{row.previousReading ?? '—'}}</template></el-table-column><el-table-column label="本期读数"><template #default="{row}">{{row.currentReading ?? '—'}}</template></el-table-column><el-table-column label="用量 / 数量"><template #default="{row}">{{row.quantity}} {{row.unitName}}</template></el-table-column><el-table-column label="单价"><template #default="{row}">{{formatMoney(row.unitPrice)}}</template></el-table-column><el-table-column label="金额"><template #default="{row}">{{formatMoney(row.amount)}}</template></el-table-column></el-table><h3>支付记录</h3><el-table :data="detail.payments" max-height="240"><el-table-column prop="paymentNo" label="支付单号"/><el-table-column prop="payerName" label="付款人"/><el-table-column label="金额"><template #default="{row}">{{formatMoney(row.amount)}}</template></el-table-column><el-table-column prop="paidAt" label="付款时间"/><el-table-column prop="paymentMethod" label="支付方式"/><el-table-column prop="status" label="支付状态"/></el-table></template></el-drawer></template>
<style scoped>.page{display:grid;gap:18px}.filters{display:grid;grid-template-columns:1.5fr 1.5fr 110px 110px 140px auto;gap:10px;margin-bottom:16px}h3{margin:22px 0 10px;font-size:15px}@media(max-width:900px){.filters{grid-template-columns:repeat(2,1fr)}}@media(max-width:560px){.filters{grid-template-columns:1fr}}</style>
